// 독립 학습용 구현: 원서의 전체 API가 아니라 경계 처리를 보여 줍니다.
inline Float SampleLinear(Float u, Float a, Float b) {
    DCHECK(a >= 0 && b >= 0 && u >= 0 && u < 1);
    if (a == 0 && b == 0) return u; // 영 함수: 균일 표본으로 정한 fallback
    if (u == 0) return 0;           // a=0인 경우의 0/0 방지
    Float x = u * (a + b) / (a + std::sqrt(Lerp(u, a * a, b * b)));
    return std::min(x, OneMinusEpsilon);
}

