    // 2. 균일 난수 u를 전체 가중치 스케일로 확장
    Float up = u * sumWeights;
    if (up == sumWeights)
        up = std::nextafter(up, -Float(Infinity));

    // 3. 누적합을 순회하며 난수 up가 속한 구간(offset) 찾기
    int offset = 0;
    Float sum = 0;
    while (sum + weights[offset] <= up) {
        sum += weights[offset++];
        DCHECK_LT(offset, weights.size());
    }

    // 4. 해당 원소가 뽑힐 확률(pmf)과 남은 난수 재활용 값(uRemap) 반환
    if (pmf) *pmf = weights[offset] / sumWeights;
    if (uRemap) *uRemap = std::min((up - sum) / weights[offset], OneMinusEpsilon);

    return offset;
}

before.content:
C++에서 가상 함수(`virtual`)를 통한 다형성은 런타임에 vtable 포인터를 거쳐야 하므로 수억 번 호출되는 3D 벡터 연산에 엄청난 성능 저하(오버헤드)를 유발합니다.

CRTP는 **컴파일 타임에 정적 다형성**을 달성하는 기법입니다:
```cpp
template <template <typename> class Child, typename T>
class Tuple3 { ... };

// 파생 클래스가 자기 자신을 부모 템플릿의 인자로 넘김!
class Vector3 : public Tuple3<Vector3, Float> { ... };
```
이렇게 하면 부모 클래스인 `Tuple3` 안에서 덧셈 연산자를 정의할 때, 부모 타입(`Tuple3`)이 아니라 **실제 자식 타입(`Vector3`)을 반환값으로 즉시 리턴**할 수 있습니다. 가상 함수 비용 없이 컴파일 타임 인라이닝과 엄격한 타입 안전성을 동시에 확보하는 현대 C++의 강력한 패턴입니다.

