bool BVHAggregate::Intersect(const Ray &ray, SurfaceInteraction *isect) const {
    if (!nodes) return false;
    Vector3f invDir(1 / ray.d.x, 1 / ray.d.y, 1 / ray.d.z);
    int dirIsNeg[3] = {invDir.x < 0, invDir.y < 0, invDir.z < 0};

    int toVisitOffset = 0, currentNodeIndex = 0;
    int nodesToVisit[64];

    while (true) {
        const LinearBVHNode *node = &nodes[currentNodeIndex];
        // 1. 슬랩 알고리즘으로 AABB 교차 검사
        if (node->bounds.IntersectP(ray, invDir, dirIsNeg)) {
            if (node->nPrimitives > 0) {
                // 리프 노드: 내부의 프리미티브들과 교차 검사
                for (int i = 0; i < node->nPrimitives; ++i)
                    primitives[node->primitivesOffset + i]->Intersect(ray, isect);
                if (toVisitOffset == 0) break;
                currentNodeIndex = nodesToVisit[--toVisitOffset];
            } else {
                // 내부 노드: 광선 방향에 따라 가까운 자식을 먼저 순회
                if (dirIsNeg[node->axis]) {
                    nodesToVisit[toVisitOffset++] = currentNodeIndex + 1;
                    currentNodeIndex = node->secondChildOffset;
                } else {
                    nodesToVisit[toVisitOffset++] = node->secondChildOffset;
                    currentNodeIndex = currentNodeIndex + 1;
                }
            }
        } else {
            if (toVisitOffset == 0) break;
            currentNodeIndex = nodesToVisit[--toVisitOffset];
        }
    }
    return isect->hit;
}

